corrected_code:
router.post('/api/support/impersonate/start', requireSupportRole, async (req, res) => {
  const { targetUserId, supportTicketId } = req.body;

  const consent = await db.query(
    'SELECT id FROM support_delegations WHERE user_id = $1 AND ticket_id = $2 AND expires_at > NOW() AND is_active = true',
    [targetUserId, supportTicketId]
  );
  if (consent.rowCount === 0) {
    return res.status(403).json({ error: 'No active user consent delegation found for this ticket' });
  }

  const sessionToken = crypto.randomBytes(32).toString('hex');
  const cachedUserState = await redis.get(`user_profile:${targetUserId}`);
  if (!cachedUserState) {
    return res.status(404).json({ error: 'User profile not found in cache' });
  }

  await redis.setex(`impersonation:${sessionToken}`, 1800, JSON.stringify({
    impersonatedUserId: targetUserId,
    originalSupportAgent: req.user.id,
    ticketId: supportTicketId
  }));

  res.json({ impersonationToken: sessionToken, targetUserId });
});
